package com.alldropsounds;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Watches inventory changes that follow a chest-loot chat message.
 * Loot can be applied either just before or just after that message.
 */
public final class ChestLootWatch
{
	static final int WATCH_TICKS = 5;

	private Map<Integer, Integer> baseline = new HashMap<>();
	private Map<Integer, Integer> inventory = new HashMap<>();
	private boolean awaiting;
	private int ticksLeft;
	private boolean startedThisTick;
	private boolean capturedThisTick;
	private List<Integer> lastLost = Collections.emptyList();

	public void reset(Map<Integer, Integer> counts)
	{
		inventory = copy(counts);
		baseline = copy(counts);
		awaiting = false;
		ticksLeft = 0;
		startedThisTick = false;
		capturedThisTick = false;
		lastLost = Collections.emptyList();
	}

	public void onGameTick()
	{
		capturedThisTick = false;
		if (startedThisTick)
		{
			startedThisTick = false;
		}
		else if (ticksLeft > 0)
		{
			ticksLeft--;
			if (ticksLeft == 0)
			{
				awaiting = false;
			}
		}

		if (!awaiting)
		{
			baseline = copy(inventory);
		}
	}

	public Map<Integer, Integer> onChestMessage()
	{
		if (capturedThisTick)
		{
			return Collections.emptyMap();
		}

		awaiting = true;
		ticksLeft = WATCH_TICKS;
		startedThisTick = true;
		lastLost = Collections.emptyList();

		Map<Integer, Integer> gained = InventoryDiff.gainedAmounts(baseline, inventory);
		if (!gained.isEmpty())
		{
			awaiting = false;
			baseline = copy(inventory);
			capturedThisTick = true;
		}
		return gained;
	}

	public Map<Integer, Integer> onInventoryChange(Map<Integer, Integer> now)
	{
		List<Integer> lost = InventoryDiff.decreased(inventory, now);
		Map<Integer, Integer> gained = Collections.emptyMap();
		if (awaiting)
		{
			gained = InventoryDiff.gainedAmounts(baseline, now);
			if (!gained.isEmpty())
			{
				awaiting = false;
				baseline = copy(now);
				capturedThisTick = true;
			}
		}

		inventory = copy(now);
		lastLost = lost;
		return gained;
	}

	public List<Integer> getLastLost()
	{
		return lastLost;
	}

	public boolean isAwaiting()
	{
		return awaiting;
	}

	private static Map<Integer, Integer> copy(Map<Integer, Integer> counts)
	{
		return counts == null ? new HashMap<>() : new HashMap<>(counts);
	}
}

package com.alldropsounds;

import net.runelite.client.util.Filepath;

/**
 * Picks the wav and volume for one item.
 * A specific item file wins, then highlighted.wav, then the price-tier file.
 * A volume of 0 or less on the chosen file means nothing should play.
 */
public final class DropSoundPlan
{
	public static final String HIGHLIGHTED_FILE = "highlighted";
	public static final String UNIQUE_FILE = "Unique";

	public static int applyMaster(int volume, int masterVolume)
	{
		if (volume <= 0 || masterVolume <= 0)
		{
			return 0;
		}

		int scaled = (int) Math.round(Math.min(100, volume) * (Math.min(100, masterVolume) / 100.0));
		return Math.min(100, Math.max(0, scaled));
	}

	public final Filepath file;
	public final int volume;

	private DropSoundPlan(Filepath file, int volume)
	{
		this.file = file;
		this.volume = volume;
	}

	public static DropSoundPlan choose(Filepath specificFile, Filepath tierFile, int itemVolume, int tierVolume)
	{
		return choose(specificFile, null, tierFile, itemVolume, 0, tierVolume);
	}

	public static DropSoundPlan choose(Filepath specificFile, Filepath highlightedFile, Filepath tierFile, int itemVolume, int highlightedVolume, int tierVolume)
	{
		if (specificFile != null)
		{
			return playable(specificFile, itemVolume);
		}
		if (highlightedFile != null)
		{
			return playable(highlightedFile, highlightedVolume);
		}
		return playable(tierFile, tierVolume);
	}

	private static DropSoundPlan playable(Filepath file, int volume)
	{
		if (file == null || volume <= 0)
		{
			return null;
		}
		return new DropSoundPlan(file, Math.min(100, volume));
	}
}

package com.alldropsounds;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public final class DropSoundPlayer
{
	private static final Logger log = LoggerFactory.getLogger(DropSoundPlayer.class);

	private final AudioPlayer audioPlayer = new AudioPlayer();
	private ExecutorService executor;

	public synchronized void play(Filepath wav, int volumePercent)
	{
		if (wav == null || volumePercent <= 0)
		{
			return;
		}

		int volume = Math.min(100, volumePercent);
		float gain = decibels(volume);
		executor().execute(() -> playNow(wav, gain));
	}

	public synchronized void shutdown()
	{
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
	}

	private ExecutorService executor()
	{
		if (executor == null || executor.isShutdown())
		{
			executor = Executors.newCachedThreadPool(runnable ->
			{
				Thread thread = new Thread(runnable, "all-drop-sounds");
				thread.setDaemon(true);
				return thread;
			});
		}
		return executor;
	}

	static float decibels(int volumePercent)
	{
		if (volumePercent <= 0)
		{
			return -80f;
		}
		if (volumePercent >= 100)
		{
			return 0f;
		}
		return (float) (20.0 * Math.log10(volumePercent / 100.0));
	}

	private void playNow(Filepath wav, float gain)
	{
		try
		{
			audioPlayer.play(wav, gain);
		}
		catch (Exception ex)
		{
			log.warn("Could not play {}", wav, ex);
		}
	}
}

package com.alldropsounds;

import net.runelite.api.SoundEffectVolume;

/**
 * Scales plugin volume by the in-game sound sliders.
 * Zero on either slider that is actually in use mutes the sound.
 */
public final class GameAudio
{
	private GameAudio()
	{
	}

	public static int outputPercent(int masterSlider, int effectsSlider)
	{
		int effects = sliderPercent(effectsSlider);
		if (effects <= 0)
		{
			return 0;
		}

		int master = masterSlider <= 0 ? 0 : sliderPercent(masterSlider);
		if (master <= 0)
		{
			return 0;
		}
		return effects * master / 100;
	}

	public static int applyOutput(int volume, int outputPercent)
	{
		if (volume <= 0 || outputPercent <= 0)
		{
			return 0;
		}
		int scaled = (int) Math.round(Math.min(100, volume) * (Math.min(100, outputPercent) / 100.0));
		return Math.max(0, Math.min(100, scaled));
	}

	static int sliderPercent(int value)
	{
		if (value <= 0)
		{
			return 0;
		}
		if (value <= 4)
		{
			return value * 25;
		}
		if (value >= SoundEffectVolume.HIGH)
		{
			return 100;
		}
		return Math.min(100, (value * 100 + SoundEffectVolume.HIGH / 2) / SoundEffectVolume.HIGH);
	}
}

package com.alldropsounds;

import net.runelite.api.TileItem;

/**
 * Decides whether a ground item spawn should make a sound.
 */
public final class GroundDropRules
{
	private GroundDropRules()
	{
	}

	public static boolean isYourDrop(int ownership)
	{
		return ownership == TileItem.OWNERSHIP_SELF || ownership == TileItem.OWNERSHIP_GROUP;
	}

	public static boolean spawnBlocked(int tickCount, int blockUntilTick)
	{
		return tickCount < blockUntilTick;
	}

	public static final int SELF_DROP_WINDOW = 4;

	public static boolean shouldPlay(boolean playItemsYouDrop, boolean onlyYourDrops, int ownership, boolean selfDrop)
	{
		if (selfDrop)
		{
			return playItemsYouDrop;
		}
		if (onlyYourDrops && !isYourDrop(ownership))
		{
			return false;
		}
		return true;
	}

	public static boolean isManualDrop(String menuOption, boolean itemOp)
	{
		return itemOp && menuOption != null && menuOption.equalsIgnoreCase("Drop");
	}

	public static boolean isRememberedDrop(Integer droppedAtTick, int spawnTick)
	{
		if (droppedAtTick == null)
		{
			return false;
		}

		long delta = (long) spawnTick - droppedAtTick;
		return delta >= -SELF_DROP_WINDOW && delta <= SELF_DROP_WINDOW;
	}

	public static boolean wasJustDropped(Integer droppedAtTick, int tickCount)
	{
		if (droppedAtTick == null)
		{
			return false;
		}

		long delta = (long) tickCount - droppedAtTick;
		return delta >= 0 && delta <= 1;
	}

	public static boolean dropExpired(int droppedAtTick, int tickCount)
	{
		long delta = (long) tickCount - droppedAtTick;
		return delta > SELF_DROP_WINDOW;
	}
}

package com.alldropsounds;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/**
 * Highlighted item names stored by Ground Items and other plugins.
 */
public final class HighlightedLists
{
	private static final Pattern QUANTITY = Pattern.compile("^(.*?)([<>])(\\d+)$");

	private HighlightedLists()
	{
	}

	public static boolean isHighlightKey(String wholeKey)
	{
		String[] parts = groupAndKey(wholeKey);
		if (parts == null)
		{
			return false;
		}

		String leaf = parts[1].toLowerCase(Locale.ENGLISH);
		if (leaf.contains("color") || leaf.contains("volume") || leaf.contains("price"))
		{
			return false;
		}
		return "highlighteditems".equals(leaf)
			|| "highlighteditem".equals(leaf)
			|| "highlightitems".equals(leaf);
	}

	public static String[] groupAndKey(String wholeKey)
	{
		if (wholeKey == null)
		{
			return null;
		}

		int dot = wholeKey.indexOf('.');
		if (dot <= 0 || dot >= wholeKey.length() - 1)
		{
			return null;
		}

		String group = wholeKey.substring(0, dot);
		String rest = wholeKey.substring(dot + 1);
		int dot2 = rest.indexOf('.');
		String key = dot2 < 0 ? rest : rest.substring(0, dot2);
		if (key.isEmpty())
		{
			return null;
		}
		return new String[] {group, key};
	}

	public static boolean isItemList(String value)
	{
		if (value == null)
		{
			return false;
		}

		String trimmed = value.trim();
		if (trimmed.isEmpty() || trimmed.equalsIgnoreCase("true") || trimmed.equalsIgnoreCase("false"))
		{
			return false;
		}
		if (trimmed.matches("#?[0-9a-fA-F]{6,8}") || trimmed.matches("-?\\d+"))
		{
			return false;
		}
		return true;
	}

	public static boolean matches(List<String> lists, String itemName, int quantity)
	{
		if (lists == null || itemName == null)
		{
			return false;
		}

		for (String list : lists)
		{
			if (!isItemList(list))
			{
				continue;
			}
			for (String entry : entries(list))
			{
				if (entryMatches(entry, itemName, quantity))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static List<String> entries(String list)
	{
		try
		{
			return Text.fromCSV(list);
		}
		catch (Exception ex)
		{
			List<String> parts = new ArrayList<String>();
			for (String part : list.split("[,;\\r\\n]+"))
			{
				parts.add(part);
			}
			return parts;
		}
	}

	static boolean entryMatches(String rawEntry, String itemName, int quantity)
	{
		if (rawEntry == null)
		{
			return false;
		}

		String entry = rawEntry.trim();
		if (entry.isEmpty())
		{
			return false;
		}

		int target = -1;
		boolean greater = false;
		Matcher quantityMatch = QUANTITY.matcher(entry);
		if (quantityMatch.matches())
		{
			entry = quantityMatch.group(1).trim();
			greater = ">".equals(quantityMatch.group(2));
			target = Integer.parseInt(quantityMatch.group(3));
		}
		if (entry.isEmpty())
		{
			return false;
		}
		if (target >= 0)
		{
			if (greater && quantity <= target)
			{
				return false;
			}
			if (!greater && quantity >= target)
			{
				return false;
			}
		}

		if (entry.indexOf('*') >= 0)
		{
			return wildcard(entry, itemName);
		}
		return itemName.equalsIgnoreCase(entry);
	}

	private static boolean wildcard(String pattern, String itemName)
	{
		StringBuilder regex = new StringBuilder("(?i)");
		for (int i = 0; i < pattern.length(); i++)
		{
			char c = pattern.charAt(i);
			if (c == '*')
			{
				regex.append(".*");
			}
			else if ("\\.^$|?+()[]{}".indexOf(c) >= 0)
			{
				regex.append('\\').append(c);
			}
			else
			{
				regex.append(c);
			}
		}
		return itemName.matches(regex.toString());
	}
}

package com.alldropsounds;

import java.util.Locale;

/**
 * Item names that must stay silent even when a wav exists or a price tier matches.
 */
public final class IgnoredItems
{
	private IgnoredItems()
	{
	}

	public static boolean contains(String list, String itemName)
	{
		String key = normalize(itemName);
		if (key == null || list == null || list.isEmpty())
		{
			return false;
		}

		String[] parts = list.split("[,;\\r\\n]+");
		for (String part : parts)
		{
			if (key.equals(normalize(part)))
			{
				return true;
			}
		}
		return false;
	}

	private static String normalize(String raw)
	{
		String cleaned = ItemNames.clean(raw);
		if (cleaned == null)
		{
			return null;
		}
		return cleaned.replaceAll("\\s+", " ").toLowerCase(Locale.ENGLISH);
	}
}

package com.alldropsounds;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Differences between two item-id to quantity maps.
 */
public final class InventoryDiff
{
	private InventoryDiff()
	{
	}

	public static List<Integer> increased(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		if (after == null || after.isEmpty())
		{
			return Collections.emptyList();
		}

		List<Integer> gained = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : after.entrySet())
		{
			int id = entry.getKey();
			if (id <= 0)
			{
				continue;
			}

			int previous = quantity(before, id);
			if (quantity(entry.getValue()) > previous)
			{
				gained.add(id);
			}
		}
		return gained;
	}

	public static Map<Integer, Integer> gainedAmounts(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		if (after == null || after.isEmpty())
		{
			return Collections.emptyMap();
		}

		Map<Integer, Integer> gained = new LinkedHashMap<>();
		for (Map.Entry<Integer, Integer> entry : after.entrySet())
		{
			int id = entry.getKey();
			if (id <= 0)
			{
				continue;
			}

			int previous = quantity(before, id);
			long added = (long) quantity(entry.getValue()) - previous;
			if (added > Integer.MAX_VALUE)
			{
				gained.put(id, Integer.MAX_VALUE);
			}
			else if (added > 0)
			{
				gained.put(id, (int) added);
			}
		}
		return gained;
	}

	public static List<Integer> decreased(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		if (before == null || before.isEmpty())
		{
			return Collections.emptyList();
		}

		List<Integer> lost = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : before.entrySet())
		{
			int id = entry.getKey();
			if (id <= 0)
			{
				continue;
			}

			long next = quantity(after, id);
			if (quantity(entry.getValue()) > next)
			{
				lost.add(id);
			}
		}
		return lost;
	}

	private static int quantity(Map<Integer, Integer> counts, int id)
	{
		if (counts == null)
		{
			return 0;
		}
		return quantity(counts.get(id));
	}

	/**
	 * Adds two stack counts without throwing when the sum does not fit in an int.
	 */
	public static int addQuantity(int left, int right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException ex)
		{
			return Integer.MAX_VALUE;
		}
	}

	private static int quantity(Integer value)
	{
		return value == null ? 0 : value;
	}
}

